<script setup lang="ts">
import {computed,ref,onMounted,onUnmounted} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {EnvelopeIcon,CodeBracketIcon,ChatBubbleLeftRightIcon,SignalIcon} from '@heroicons/vue/24/outline'
import PageHeading from '../components/PageHeading.vue'
import {api,bootstrap,notify} from '../composables/api'
import {useCollaborationAction} from '../composables/collaboration'
import {date} from '../composables/investigation'
import type {IntegrationConfiguration,IntegrationConnection,TestDeliveryOperation} from '../types'
type Provider='slack'|'webhook'|'github'
const data=ref<IntegrationConfiguration|null>(null),loading=ref(true),error=ref(''),saving=ref(false),selected=ref<Provider|null>(null),editing=ref<string|null>(null),replacing=ref<IntegrationConnection|null>(null),form=ref({name:'',enabled:false,endpoint:'',owner:'',repo:'',credential:'',credential_reference:'',events:[] as string[],automatic:false,environments:[] as string[],labels:[] as string[]}),baseline=ref(''),version=ref(0),editor=ref(false)
const once=ref<{secret:string;key_id:string;state:string}|null>(null),testConfirmation=ref<{id:string;key?:string}|null>(null),operation=ref<TestDeliveryOperation|null>(null),polling=ref(false),tokenEditor=ref(false)
const perform=useCollaborationAction(),current=computed(()=>data.value?.connections.find(c=>c.id===editing.value)),dirty=computed(()=>editor.value&&baseline.value!==JSON.stringify(form.value)),canManage=computed(()=>bootstrap.value?.capabilities.manage)
const providers=[{id:'email',name:'Email',description:'Host mailer · one canonical recipient per destination',icon:EnvelopeIcon},{id:'github',name:'GitHub Issues',description:'Create or link a ticket in a configured repository',icon:CodeBracketIcon},{id:'slack',name:'Slack',description:'Incoming webhooks · channel label supplied by your administrator',icon:ChatBubbleLeftRightIcon},{id:'webhook',name:'Webhooks',description:'Signed events for your tools · exact-body verification',icon:SignalIcon}]
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false,checks=0
function leave(){return (!dirty.value&&!once.value)||window.confirm(once.value?'Copy this signing key before leaving. It cannot be shown again. Continue?':'Discard your unsaved integration draft?')}
onBeforeRouteLeave(leave)
const unload=(e:BeforeUnloadEvent)=>{if(dirty.value||once.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{load();window.addEventListener('beforeunload',unload)});onUnmounted(()=>{disposed=true;clearTimeout(timer);window.removeEventListener('beforeunload',unload)})
async function load(){loading.value=true;try{data.value=await api('/integrations');error.value=''}catch(e){error.value=e instanceof Error?e.message:'Integrations unavailable.'}finally{loading.value=false}}
function connections(p:string){return data.value?.connections.filter(c=>c.provider===p)??[]}
function readiness(p:string){const list=connections(p);if(!list.length)return 'Not configured';if(list.some(c=>c.state==='unreadable'||['failed','retrying'].includes(c.last_test_outcome??'')))return 'Needs attention';return list.some(c=>c.enabled&&!c.disconnected)?'Configured':'Disabled'}
function choose(p:Provider,c?:IntegrationConnection,replace=false){if(!leave())return;once.value=null;selected.value=p;editor.value=!!c||connections(p).length===0;editing.value=c&&!replace?c.id:null;replacing.value=replace&&c?c:null;version.value=c?.version??0;tokenEditor.value=false;form.value={name:c?.name??'',enabled:c?.enabled??false,endpoint:'',owner:replace?'':c?.target.owner??'',repo:replace?'':c?.target.repo??'',credential:'',credential_reference:'',events:c?.options.events??Object.keys(data.value?.events??{}),automatic:c?.options.automatic??false,environments:c?.options.environments??[],labels:c?.options.labels??[]};baseline.value=JSON.stringify(form.value);error.value=''}
function add(){if(!selected.value||!leave())return;const p=selected.value;choose(p);editor.value=true}
async function save(){if(!selected.value)return;saving.value=true;try{let values:Record<string,unknown>;if(editing.value)values={version:version.value,name:form.value.name,enabled:form.value.enabled,...(selected.value==='github'?{automatic:form.value.automatic,environments:form.value.environments,labels:form.value.labels}:selected.value==='webhook'?{events:form.value.events}:{})};else {const {labels:omittedLabels,...newValues}=form.value;values={provider:selected.value,...newValues,...(replacing.value?{replaces:replacing.value.id,replaces_version:replacing.value.version}:{})}};const result=await perform<{id:string;version:number;once?:typeof once.value}>('/integrations'+(editing.value?'/'+editing.value:''),editing.value?'PATCH':'POST',values);baseline.value=JSON.stringify(form.value);editor.value=false;await load();const c=data.value?.connections.find(c=>c.id===result.id);if(c){editing.value=c.id;version.value=c.version}once.value=result.once??null;notify('Integration saved. Existing work keeps its original target.')}catch(e){error.value=e instanceof Error?e.message:'Save failed.'}finally{saving.value=false}}
async function action(c:IntegrationConnection,kind:string,values:Record<string,unknown>={}){if(once.value){error.value='Save and acknowledge the one-time signing key before changing credentials.';return}saving.value=true;try{const result=await perform<{once?:typeof once.value;id:string;version:number}>('/integrations/'+c.id+'/'+kind,'POST',{version:c.version,...values});once.value=result.once??null;await load();version.value=result.version??version.value;notify(kind==='key.stage'?'New key staged. Configure the receiver, test it, then activate explicitly.':'Integration updated.')}catch(e){error.value=e instanceof Error?e.message:'Operation failed.'}finally{saving.value=false}}
async function activate(c:IntegrationConnection,key:string){if(window.confirm('Activate this signing key? Configure the receiver first. The previous key has a 24-hour transition.'))await action(c,'key.activate',{key_id:key})}
async function disconnect(c:IntegrationConnection){if(!window.confirm('Disconnect this target? Pending work is cancelled. In-flight requests cannot be recalled.'))return;saving.value=true;try{await perform('/integrations/'+c.id,'DELETE',{version:c.version});editor.value=false;baseline.value=JSON.stringify(form.value);await load()}catch(e){error.value=e instanceof Error?e.message:'Disconnect failed.'}finally{saving.value=false}}
async function test(){if(!testConfirmation.value)return;saving.value=true;try{const v=testConfirmation.value;const result=await perform<{id:string}>('/integrations/'+v.id+'/test','POST',v.key?{signing_key_id:v.key}:{});testConfirmation.value=null;checks=0;operation.value={id:result.id,items:[],queue_asynchronous:true};polling.value=true;await poll()}catch(e){error.value=e instanceof Error?e.message:'Test could not be queued.'}finally{saving.value=false}}
async function poll(){if(!operation.value||disposed)return;try{operation.value=await api('/alerting/tests/'+operation.value.id);checks++;if(operation.value?.items.some(i=>['pending','processing','retrying'].includes(i.status))&&checks<15){polling.value=true;timer=setTimeout(poll,2000)}else{polling.value=false;await load()}}catch(e){polling.value=false;error.value=e instanceof Error?e.message:'Test status unavailable.'}}
async function reloadDraft(){if(!leave())return;once.value=null;editor.value=false;await load();if(current.value)choose(current.value.provider,current.value)}
</script>
<template>
<PageHeading title="Integrations" subtitle="Notification destinations and issue tracking, in one place."><span class="badge">Credentials are encrypted and never redisplayed</span></PageHeading>
<p v-if="bootstrap?.features.controlled_integrations" class="notice neutral">Controlled preview · no external requests are sent.</p>
<div v-if="error" class="notice danger" role="alert"><div>{{error}}<button class="button" @click="reloadDraft">Reload current configuration</button><p class="help">Your draft remains here until you choose to replace it.</p></div></div>
<p v-if="loading" role="status">Loading integrations…</p>
<div v-if="data" class="integration-list"><article v-for="p in providers" :key="p.id" class="integration-row"><component :is="p.icon" class="integration-icon"/><div><h2>{{p.name}}</h2><p>{{p.description}}</p></div><span v-if="p.id!=='email'" class="status-badge" :class="readiness(p.id)==='Needs attention'?'status-failed':''">{{readiness(p.id)}}</span><span v-else class="badge">Host managed</span><RouterLink v-if="p.id==='email'" to="/settings/email" class="button">Review email</RouterLink><button v-else class="button" @click="choose(p.id as Provider)">{{canManage?'Configure':'Review'}}</button></article></div>
<p class="help spacing">Connection checks and individual delivery outcomes are tracked separately. A successful GitHub read check cannot prove that every write will succeed.</p>
<section v-if="selected&&data" class="integration-workspace">
<div class="section-heading"><h2>{{selected==='github'?'GitHub repositories':selected==='slack'?'Slack destinations':'Signed webhook destinations'}}</h2><button v-if="canManage" class="button" :disabled="saving" @click="add">Add {{selected==='github'?'repository':'destination'}}</button></div>
<p v-if="!connections(selected).length" class="help">No connection configured yet.</p>
<article v-for="c in connections(selected)" :key="c.id" class="connection-row"><div class="section-heading"><div><h3>{{c.name}}</h3><p>{{c.display}}</p></div><span class="badge">{{c.disconnected?'Disconnected':c.enabled?'Enabled':'Disabled'}}</span></div><p v-if="selected==='slack'" class="help">This name is an administrator-supplied label, not a verified Slack channel identity.</p><dl class="connection-observations"><div><dt>Last {{selected==='github'?'read check':'test'}}</dt><dd>{{c.last_test_outcome??'Not tested'}} · {{date(c.last_test_at)}}</dd></div><div><dt>Last transport acceptance</dt><dd>{{date(c.last_accepted_at)}}</dd></div><div><dt>Failures / Needs review</dt><dd>{{c.failed_count}}</dd></div></dl><p v-if="c.state==='unreadable'" class="notice warning">An active credential could not be read. Restore host key availability or replace the credential.</p>
<div v-if="canManage" class="inline-actions"><button class="button" :disabled="saving" @click="choose(c.provider,c)">Edit configuration</button><button v-if="!c.disconnected" class="button" :disabled="saving||dirty||polling" @click="testConfirmation={id:c.id}">{{selected==='github'?'Check repository access':'Send synthetic test'}}</button><button class="button" :disabled="saving" @click="choose(c.provider,c,true)">Replace target</button><button v-if="!c.disconnected" class="text-link danger-link" :disabled="saving" @click="disconnect(c)">Disconnect</button></div>
<template v-if="c.provider==='webhook'&&canManage"><div class="signing-keys"><h4>Signing keys</h4><p class="help">Stage a key, configure your receiver, send a labeled test, then activate. Keep the previous key for the displayed transition deadline.</p><ul><li v-for="k in c.keys?.filter(k=>k.purpose==='webhook_signing')" :key="k.id"><span class="code">{{k.id}}</span> · {{k.state}}<span v-if="k.retire_after"> · transition ends {{date(k.retire_after)}}</span><div v-if="k.state==='staged'" class="inline-actions"><button class="button" :disabled="saving||dirty||polling" @click="testConfirmation={id:c.id,key:k.id}">Test staged key</button><button class="button" :disabled="saving||dirty||!!once" @click="activate(c,k.id)">Activate key</button></div></li></ul><button class="button" :disabled="saving||dirty||!!once" @click="action(c,'key.stage')">Stage signing key</button></div></template>
<RouterLink :to="{path:'/alerts/history',query:{channel:c.provider}}" class="text-link">Inspect {{c.provider}} delivery history</RouterLink></article>
<form v-if="editor&&canManage" class="panel integration-editor" @submit.prevent="save"><h3>{{editing?'Edit configuration':replacing?'Replace immutable target':'New connection'}}</h3><p class="help">Changing the target creates a separate destination and disconnects the old one. Pending work is never redirected.</p><label class="field">Display name<input v-model="form.name" required maxlength="120"></label>
<template v-if="!editing"><div v-if="selected==='github'" class="integration-repository-fields"><label class="field">Repository owner<input v-model="form.owner" required autocomplete="off"></label><label class="field">Repository name<input v-model="form.repo" required autocomplete="off"></label></div><label v-else class="field">{{selected==='slack'?'Slack incoming webhook URL':'HTTPS endpoint'}}<input v-model="form.endpoint" type="password" :required="!form.credential_reference" autocomplete="new-password" spellcheck="false"><small>The endpoint is stored encrypted. It will not be redisplayed.</small></label><template v-if="selected==='github'"><label class="field">Fine-grained repository token<input v-model="form.credential" type="password" :required="!form.credential_reference" autocomplete="new-password"><small>Repository Issues write permission is required for creation. A check only reads repository metadata and available labels.</small></label></template><label v-if="data.credential_references.length&&selected!=='webhook'" class="field">Or use a deployment credential reference<select v-model="form.credential_reference"><option value="">Use the entered credential</option><option v-for="r in data.credential_references" :key="r">{{r}}</option></select></label></template>
<template v-if="selected==='github'"><label class="checkbox-row"><input v-model="form.automatic" type="checkbox">Create a GitHub issue automatically for new live errors</label><p class="help">Opt-in only. Regressions retain their association; reconciliation and test captures never create tickets.</p><label v-if="form.automatic" class="field">Explicit automatic-creation environments<select v-model="form.environments" multiple required :size="Math.min(4,data.allowed_environments.length)"><option v-for="env in data.allowed_environments" :key="env">{{env}}</option></select></label><fieldset v-if="editing&&current?.options.known_labels?.length"><legend>Existing repository labels</legend><label v-for="label in current.options.known_labels" :key="label" class="checkbox-row"><input v-model="form.labels" type="checkbox" :value="label">{{label}}</label></fieldset><p v-else class="help">Run a read-only repository check after saving to load existing labels.</p></template>
<fieldset v-if="selected==='webhook'"><legend>Allowed webhook events</legend><label v-for="(label,event) in data.events" :key="event" class="checkbox-row"><input v-model="form.events" type="checkbox" :value="event">{{label}}</label></fieldset><label class="checkbox-row"><input v-model="form.enabled" type="checkbox">Enable this connection</label><div class="inline-actions spacing"><button class="button primary" :disabled="saving">{{saving?'Saving…':'Save connection'}}</button><button type="button" class="button" :disabled="saving" @click="leave()&&(editor=false)">Cancel draft</button><span v-if="dirty" class="unsaved">Unsaved changes</span></div>
<template v-if="editing&&selected==='github'&&current"><hr><h4>Replace repository token</h4><label class="field">New token<input v-model="form.credential" type="password" autocomplete="new-password"></label><button type="button" class="button" :disabled="saving||!form.credential||!!once" @click="action(current,'secret.replace',{credential:form.credential});form.credential=''">Replace token</button><p class="help">The repository stays fixed; workers load the current credential at execution.</p></template></form>
</section>
<section v-if="once" class="notice warning one-time-secret" role="status"><div><h3>Copy this {{once.state}} signing key now</h3><p>It cannot be retrieved again. Configure the receiver before sending or activating it.</p><label class="field">Key identifier<input :value="once.key_id" readonly></label><label class="field">Shared secret<input :value="once.secret" readonly autocomplete="off" spellcheck="false"></label><button class="button" @click="once=null">I saved this key</button></div></section>
<section v-if="testConfirmation" class="notice warning" role="alert"><div><h3>Confirm integration test</h3><p v-if="selected==='github'">Read repository metadata and existing labels. This does not create a GitHub issue or prove write access.</p><p v-else>Queue one labeled synthetic message to the configured destination{{testConfirmation.key?' using the staged key without activating it':''}}. {{bootstrap?.features.controlled_integrations?'This uses the controlled preview transport.':'This contacts the real configured endpoint.'}}</p><div class="inline-actions"><button class="button primary" :disabled="saving" @click="test">Confirm queued test</button><button class="button" :disabled="saving" @click="testConfirmation=null">Cancel test</button></div></div></section>
<section v-if="operation" class="panel integration-test-result" role="status"><h3>{{polling?'Checking queued operation…':'Test operation'}}</h3><ul><li v-for="item in operation.items" :key="item.id"><RouterLink :to="'/alerts/history/'+item.id">{{item.destination_name}} · {{item.status}}</RouterLink><span v-if="item.reason"> · {{item.reason}}</span></li></ul><p v-if="!operation.queue_asynchronous" class="help">No supported asynchronous queue is configured. Intent remains durable.</p><p class="help">Acceptance is an observation of this attempt, not proof of future delivery or a currently running worker.</p><button class="button" :disabled="polling" @click="checks=0;poll()">Refresh operation</button></section>
</template>
